// config/index.js
require('dotenv').config();

class Config {
  constructor() {
    this.validate();
  }

  validate() {
    if (process.env.NODE_ENV === 'production') {
      const required = ['DATABASE_URL', 'JWT_SECRET'];
      required.forEach(key => {
        if (!process.env[key]) {
          throw new Error(`Missing ${key} in production`);
        }
      });
