/**
 * Secure Secret Manager
 * Implements proper secret management with validation, encryption, and rotation
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class SecretManager {
  constructor(options = {}) {
    this.env = process.env.NODE_ENV || 'development';
    this.secrets = {};
    this.validators = {};
    this.encryptionKey = options.encryptionKey || process.env.SECRET_ENCRYPTION_KEY;

    this.initializeValidators();
  }

  initializeValidators() {
    // Define validation rules for each secret type
    this.validators = {
      JWT_SECRET: {
        required: true,
        minLength: 32,
        pattern: /^[A-Za-z0-9-_]+$/,
        description: 'JWT signing secret',
        envSpecific: true
      },
      DATABASE_URL: {
        required: this.env === 'production',
        pattern: /^(postgres|mysql|mongodb):\/\/.*/,
        description: 'Database connection URL',
        mask: true
      },
      AWS_ACCESS_KEY_ID: {
        required: false,
        pattern: /^AKIA[0-9A-Z]{16}$/,
        description: 'AWS Access Key ID',
        envSpecific: true
      },
      AWS_SECRET_ACCESS_KEY: {
        required: false,
        minLength: 40,
        description: 'AWS Secret Access Key',
        mask: true
      },
      STRIPE_SECRET_KEY: {
        required: false,
        pattern: /^sk_(live|test)_[a-zA-Z0-9]{24,}$/,
        description: 'Stripe secret key',
        mask: true,
        envSpecific: true
      },
      PORT: {
        required: false,
        default: '3000',
        pattern: /^[0-9]{2,5}$/,
        description: 'Application port'
      }
    };
  }

  /**
   * Load secrets from environment with validation
   */
  async loadSecrets() {
    console.log(`Loading secrets for ${this.env} environment`);

    // Load from environment variables
    for (const [key, validator] of Object.entries(this.validators)) {
      let value = process.env[key];

      // Apply default if not set and not required
      if (!value && validator.default && !validator.required) {
        value = validator.default;
      }

      // Validate required secrets
      if (validator.required && !value) {
        throw new Error(`Required secret ${key} is missing (${validator.description})`);
      }

      // Validate pattern if provided
      if (value && validator.pattern && !validator.pattern.test(value)) {
        throw new Error(`Secret ${key} does not match expected pattern`);
      }

      // Validate length
      if (value && validator.minLength && value.length < validator.minLength) {
        throw new Error(`Secret ${key} is too short (min ${validator.minLength} chars)`);
      }

      // Store the secret
      if (value) {
        this.secrets[key] = value;

        // Log (but mask sensitive values)
        const displayValue = validator.mask ? this.maskSecret(value) : '[SET]';
        console.log(`  ${key}: ${displayValue}`);
      }
    }

    // Load from encrypted file if exists
    await this.loadEncryptedSecrets();

    // Validate all loaded secrets
    await this.validateSecrets();

    console.log(`Successfully loaded ${Object.keys(this.secrets).length} secrets`);
    return this.secrets;
  }

  /**
   * Mask sensitive values for logging
   */
  maskSecret(value, visibleChars = 4) {
    if (!value || value.length <= visibleChars * 2) {
      return '***';
    }
    const firstPart = value.substring(0, visibleChars);
    const lastPart = value.substring(value.length - visibleChars);
    return `${firstPart}***${lastPart}`;
  }

  /**
   * Load secrets from encrypted file
   */
  async loadEncryptedSecrets() {
    const encryptedFile = path.join(__dirname, `.secrets.${this.env}.enc`);

    if (fs.existsSync(encryptedFile) && this.encryptionKey) {
      try {
        const encryptedData = fs.readFileSync(encryptedFile, 'utf8');
        const decryptedData = this.decrypt(encryptedData);
        const fileSecrets = JSON.parse(decryptedData);

        // Merge with environment secrets (environment takes precedence)
        this.secrets = { ...fileSecrets, ...this.secrets };
        console.log(`Loaded ${Object.keys(fileSecrets).length} secrets from encrypted file`);
      } catch (error) {
        console.error('Failed to load encrypted secrets:', error.message);
      }
    }
  }

  /**
   * Encrypt data
   */
  encrypt(text) {
    if (!this.encryptionKey) {
      throw new Error('Encryption key not configured');
    }

    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', 
      crypto.createHash('sha256').update(this.encryptionKey).digest(), 
      iv
    );

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex');

    return JSON.stringify({
      iv: iv.toString('hex'),
      encrypted,
      authTag
    });
  }

  /**
   * Decrypt data
   */
  decrypt(encryptedData) {
    if (!this.encryptionKey) {
      throw new Error('Encryption key not configured');
    }

    const { iv, encrypted, authTag } = JSON.parse(encryptedData);
    const decipher = crypto.createDecipheriv('aes-256-gcm',
      crypto.createHash('sha256').update(this.encryptionKey).digest(),
      Buffer.from(iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  /**
   * Get a secret value
   */
  get(key, defaultValue) {
    const value = this.secrets[key];

    if (value === undefined && defaultValue === undefined) {
      throw new Error(`Secret ${key} not found and no default provided`);
    }

    return value !== undefined ? value : defaultValue;
  }

  /**
   * Get masked secret for logging
   */
  getMasked(key) {
    const value = this.get(key);
    const validator = this.validators[key];

    if (validator && validator.mask) {
      return this.maskSecret(value);
    }

    return '[SET]';
  }

  /**
   * Validate all loaded secrets
   */
  async validateSecrets() {
    const validationErrors = [];

    for (const [key, value] of Object.entries(this.secrets)) {
      const validator = this.validators[key];

      if (validator) {
        // Check if secret is environment-specific
        if (validator.envSpecific) {
          const envIndicator = this.env === 'production' ? 'prod' : 
                              this.env === 'staging' ? 'stage' : 'dev';

          if (!value.includes(envIndicator) && !value.includes('CANARY')) {
            console.warn(`Warning: Secret ${key} may not be environment-specific`);
          }
        }

        // Check for default/placeholder values in production
        if (this.env === 'production') {
          if (value.includes('CANARY') || 
              value.includes('change-in-production') ||
              value.includes('example') ||
              value.includes('placeholder')) {
            validationErrors.push(`Production secret ${key} contains placeholder value`);
          }
        }
      }
    }

    if (validationErrors.length > 0) {
      throw new Error(`Secret validation failed:\n${validationErrors.join('\n')}`);
    }

    return true;
  }

  /**
   * Check for common security issues
   */
  securityAudit() {
    const issues = [];

    // Check for hardcoded secrets
    const hardcodedPatterns = [
      /password\s*=\s*["'][^"']{4,}["']/,
      /secret\s*=\s*["'][^"']{4,}["']/,
      /key\s*=\s*["'][^"']{4,}["']/,
      /token\s*=\s*["'][^"']{4,}["']/
    ];

    // Check current directory JS files
    const jsFiles = fs.readdirSync(__dirname)
      .filter(file => file.endsWith('.js') && file !== 'secrets-manager.js');

    jsFiles.forEach(file => {
      const content = fs.readFileSync(path.join(__dirname, file), 'utf8');

      hardcodedPatterns.forEach(pattern => {
        if (pattern.test(content)) {
          issues.push(`Potential hardcoded secret in ${file}`);
        }
      });
    });

    // Check for .env files in git
    if (fs.existsSync(path.join(__dirname, '.git'))) {
      const gitignore = fs.existsSync(path.join(__dirname, '.gitignore')) 
        ? fs.readFileSync(path.join(__dirname, '.gitignore'), 'utf8')
        : '';

      if (!gitignore.includes('.env') && !gitignore.includes('.env*')) {
        issues.push('.env files not excluded from git');
      }
    }

    return issues;
  }

  /**
   * Rotate a secret
   */
  async rotateSecret(key, newValue) {
    if (!this.validators[key]) {
      throw new Error(`No validator found for secret ${key}`);
    }

    // Validate new value
    const validator = this.validators[key];
    if (validator.pattern && !validator.pattern.test(newValue)) {
      throw new Error(`New value for ${key} does not match required pattern`);
    }

    if (validator.minLength && newValue.length < validator.minLength) {
      throw new Error(`New value for ${key} is too short (min ${validator.minLength} chars)`);
    }

    // Update in memory
    const oldValue = this.secrets[key];
    this.secrets[key] = newValue;

    // Log the rotation
    console.log(`Rotated secret ${key} from ${this.maskSecret(oldValue)} to ${this.maskSecret(newValue)}`);

    return true;
  }
}

// Factory function for creating secret manager
function createSecretManager(options = {}) {
  const manager = new SecretManager(options);

  // Auto-load secrets
  manager.loadSecrets().catch(error => {
    console.error('Failed to load secrets:', error.message);

    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  });

  return manager;
}

module.exports = {
  SecretManager,
  createSecretManager
};

