/**
 * External Secrets Manager Integration
 * Supports AWS Secrets Manager, HashiCorp Vault, and Kubernetes Secrets
 */

const axios = require('axios');
const crypto = require('crypto');

class ExternalSecretManager {
  constructor(config = {}) {
    this.config = {
      provider: config.provider || process.env.SECRET_PROVIDER || 'env',
      cacheDuration: config.cacheDuration || 300000, // 5 minutes
      enableCache: config.enableCache !== false,
      fallbackToEnv: config.fallbackToEnv !== false
    };

    this.cache = new Map();
    this.lastFetchTime = 0;
    this.secrets = {};
  }

  /**
   * Get a secret from external provider
   */
  async getSecret(key, defaultValue) {
    // Check cache first
    if (this.config.enableCache && this.cache.has(key)) {
      const cached = this.cache.get(key);
      if (Date.now() - cached.timestamp < this.config.cacheDuration) {
        return cached.value;
      }
    }

    let value;

    try {
      switch (this.config.provider.toLowerCase()) {
        case 'aws':
          value = await this.getFromAWS(key);
          break;
        case 'vault':
          value = await this.getFromVault(key);
          break;
        case 'kubernetes':
          value = await this.getFromKubernetes(key);
          break;
        case 'azure':
          value = await this.getFromAzure(key);
          break;
        case 'gcp':
          value = await this.getFromGCP(key);
          break;
        default:
          value = process.env[key];
      }
    } catch (error) {
      console.error(`Failed to fetch secret ${key} from ${this.config.provider}:`, error.message);
      value = process.env[key]; // Fallback to environment
    }

    // Use default if still not found
    if (value === undefined && defaultValue !== undefined) {
      value = defaultValue;
    }

    // Cache the value
    if (this.config.enableCache && value !== undefined) {
      this.cache.set(key, {
        value,
        timestamp: Date.now()
      });
    }

    return value;
  }

  /**
   * Fetch from AWS Secrets Manager
   */
  async getFromAWS(secretId) {
    if (!process.env.AWS_REGION) {
      throw new Error('AWS_REGION not configured');
    }

    // In production, you would use AWS SDK
    // This is a simplified implementation

    const region = process.env.AWS_REGION;
    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      throw new Error('AWS credentials not configured');
    }

    // For development/testing, we can mock this
    if (process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test') {
      return this.mockAWSCall(secretId);
    }

    // In production, you would use AWS SDK:
    // const AWS = require('aws-sdk');
    // const client = new AWS.SecretsManager({region});
    // const response = await client.getSecretValue({SecretId: secretId}).promise();
    // return JSON.parse(response.SecretString)[secretId];

    throw new Error('AWS Secrets Manager integration not fully implemented');
  }

  /**
   * Fetch from HashiCorp Vault
   */
  async getFromVault(path) {
    const vaultAddr = process.env.VAULT_ADDR;
    const vaultToken = process.env.VAULT_TOKEN;

    if (!vaultAddr || !vaultToken) {
      throw new Error('Vault configuration missing');
    }

    try {
      const response = await axios.get(`${vaultAddr}/v1/secret/data/${path}`, {
        headers: {
          'X-Vault-Token': vaultToken
        },
        timeout: 5000
      });

      return response.data.data.data[path.split('/').pop()];
    } catch (error) {
      console.error('Vault request failed:', error.message);
      throw error;
    }
  }

  /**
   * Fetch from Kubernetes Secrets
   */
  async getFromKubernetes(secretName) {
    // Kubernetes secrets are mounted as files
    const fs = require('fs');
    const path = require('path');

    const secretPath = `/var/run/secrets/kubernetes.io/${secretName}`;

    if (fs.existsSync(secretPath)) {
      return fs.readFileSync(secretPath, 'utf8').trim();
    }

    // Check alternative path
    const altPath = path.join('/etc/secrets', secretName);
    if (fs.existsSync(altPath)) {
      return fs.readFileSync(altPath, 'utf8').trim();
    }

    throw new Error(`Kubernetes secret ${secretName} not found`);
  }

  /**
   * Fetch from Azure Key Vault
   */
  async getFromAzure(secretName) {
    const keyVaultName = process.env.AZURE_KEY_VAULT_NAME;
    const clientId = process.env.AZURE_CLIENT_ID;
    const clientSecret = process.env.AZURE_CLIENT_SECRET;
    const tenantId = process.env.AZURE_TENANT_ID;

    if (!keyVaultName || !clientId || !clientSecret || !tenantId) {
      throw new Error('Azure Key Vault configuration missing');
    }

    // Simplified - in production use @azure/keyvault-secrets package
    const vaultUrl = `https://${keyVaultName}.vault.azure.net`;

    try {
      // Get access token
      const tokenResponse = await axios.post(
        `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`,
        new URLSearchParams({
          client_id: clientId,
          client_secret: clientSecret,
          scope: 'https://vault.azure.net/.default',
          grant_type: 'client_credentials'
        }),
        {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          }
        }
      );

      const accessToken = tokenResponse.data.access_token;

      // Get secret value
      const secretResponse = await axios.get(
        `${vaultUrl}/secrets/${secretName}?api-version=7.3`,
        {
          headers: {
            'Authorization': `Bearer ${accessToken}`
          }
        }
      );

      return secretResponse.data.value;
    } catch (error) {
      console.error('Azure Key Vault request failed:', error.message);
      throw error;
    }
  }

  /**
   * Fetch from Google Cloud Secret Manager
   */
  async getFromGCP(secretName) {
    const projectId = process.env.GOOGLE_CLOUD_PROJECT;

    if (!projectId) {
      throw new Error('Google Cloud project not configured');
    }

    // Simplified - in production use @google-cloud/secret-manager
    const secretManagerUrl = `https://secretmanager.googleapis.com/v1/projects/${projectId}/secrets/${secretName}/versions/latest:access`;

    try {
      // GCP typically uses Application Default Credentials
      // For simplicity, we'll use an API key here
      const apiKey = process.env.GOOGLE_API_KEY;

      if (!apiKey) {
        throw new Error('Google Cloud API key not configured');
      }

      const response = await axios.get(secretManagerUrl, {
        headers: {
          'Authorization': `Bearer ${apiKey}`
        }
      });

      return Buffer.from(response.data.payload.data, 'base64').toString('utf8');
    } catch (error) {
      console.error('Google Cloud Secret Manager request failed:', error.message);
      throw error;
    }
  }

  /**
   * Mock AWS call for development
   */
  mockAWSCall(secretId) {
    // Map secret IDs to environment variables for development
    const mapping = {
      'jwt-secret': 'JWT_SECRET',
      'database-url': 'DATABASE_URL',
      'aws-access-key-id': 'AWS_ACCESS_KEY_ID',
      'aws-secret-access-key': 'AWS_SECRET_ACCESS_KEY',
      'stripe-secret-key': 'STRIPE_SECRET_KEY'
    };

    const envVar = mapping[secretId] || secretId;
    return process.env[envVar];
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(keys) {
    const results = {};
    const promises = [];

    for (const key of keys) {
      promises.push(
        this.getSecret(key).then(value => {
          results[key] = value;
        })
      );
    }

    await Promise.all(promises);
    return results;
  }

  /**
   * Rotate a secret
   */
  async rotateSecret(key, newValue) {
    console.log(`Rotating secret ${key} in ${this.config.provider}`);

    // In production, you would call the provider's rotation API
    // For now, just update the cache

    if (this.config.enableCache) {
      this.cache.set(key, {
        value: newValue,
        timestamp: Date.now()
      });
    }

    return true;
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.cache.clear();
    this.lastFetchTime = 0;
    return true;
  }

  /**
   * Health check
   */
  async healthCheck() {
    try {
      // Try to fetch a test secret
      await this.getSecret('test-secret-health-check');
      return {
        status: 'healthy',
        provider: this.config.provider,
        cacheSize: this.cache.size,
        cacheEnabled: this.config.enableCache
      };
    } catch (error) {
      return {
        status: 'unhealthy',
        provider: this.config.provider,
        error: error.message
      };
    }
  }
}

// Factory function
function createExternalSecretManager(config = {}) {
  return new ExternalSecretManager(config);
}

module.exports = {
  ExternalSecretManager,
  createExternalSecretManager
};

/**
 * Secret Management Configuration
 * Defines how secrets are loaded and managed based on environment
 */

const fs = require('fs');
const path = require('path');

// Environment-specific configurations
const SECRET_CONFIG = {
  development: {
    provider: 'env', // Use environment variables
    encryption: false,
    validation: {
      strict: false,
      allowDefaults: true
    },
    sources: [
      '.env.development',
      '.env.local',
      '.env'
    ],
    fallback: {
      JWT_SECRET: 'dev-jwt-secret-change-in-production',
      DATABASE_URL: 'postgres://localhost:5432/dev_db',
      PORT: '3000'
    }
  },

  test: {
    provider: 'env',
    encryption: false,
    validation: {
      strict: true,
      allowDefaults: false
    },
    sources: [
      '.env.test',
      '.env'
    ],
    required: [
      'JWT_SECRET',
      'DATABASE_URL'
    ]
  },

  staging: {
    provider: 'aws', // Use AWS Secrets Manager
    encryption: true,
    validation: {
      strict: true,
      allowDefaults: false
    },
    sources: [
      'aws:///app/staging/secrets'
    ],
    required: [
      'JWT_SECRET',
      'DATABASE_URL',
      'AWS_REGION',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ]
  },

  production: {
    provider: 'vault', // Use HashiCorp Vault
    encryption: true,
    validation: {
      strict: true,
      allowDefaults: false,
      rejectPlaceholders: true
    },
    sources: [
      'vault:///secret/data/production/app',
      'env' // Fallback to env for non-sensitive configs
    ],
    required: [
      'JWT_SECRET',
      'DATABASE_URL',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ],
    rotation: {
      enabled: true,
      interval: '30d', // Rotate every 30 days
      autoRotate: true
    }
  }
};

// Secret definitions with metadata
const SECRET_DEFINITIONS = {
  JWT_SECRET: {
    type: 'string',
    minLength: 32,
    maxLength: 512,
    pattern: /^[A-Za-z0-9\-_]+$/,
    description: 'JSON Web Token signing secret',
    sensitive: true,
    rotation: '30d',
    environments: ['development', 'test', 'staging', 'production']
  },

  DATABASE_URL: {
    type: 'string',
    pattern: /^(postgres|mysql|mongodb):\/\/.+/,
    description: 'Database connection URL',
    sensitive: true,
    mask: true,
    environments: ['development', 'test', 'staging', 'production']
  },

  AWS_ACCESS_KEY_ID: {
    type: 'string',
    pattern: /^AKIA[0-9A-Z]{16}$/,
    description: 'AWS Access Key ID',
    sensitive: true,
    environments: ['staging', 'production']
  },

  AWS_SECRET_ACCESS_KEY: {
    type: 'string',
    minLength: 40,
    description: 'AWS Secret Access Key',
    sensitive: true,
    mask: true,
    environments: ['staging', 'production']
  },

  STRIPE_SECRET_KEY: {
    type: 'string',
    pattern: /^sk_(live|test)_[a-zA-Z0-9]{24,}$/,
    description: 'Stripe secret key',
    sensitive: true,
    mask: true,
    environments: ['staging', 'production']
  },

  ANTHROPIC_API_KEY: {
    type: 'string',
    pattern: /^sk-ant-[a-zA-Z0-9-]+$/,
    description: 'Anthropic API key',
    sensitive: true,
    environments: ['development', 'staging', 'production']
  },

  PORT: {
    type: 'number',
    min: 1024,
    max: 65535,
    description: 'Application port',
    sensitive: false,
    default: 3000,
    environments: ['development', 'test', 'staging', 'production']
  },

  NODE_ENV: {
    type: 'string',
    pattern: /^(development|test|staging|production)$/,
    description: 'Node environment',
    sensitive: false,
    default: 'development',
    environments: ['development', 'test', 'staging', 'production']
  },

  ALLOWED_ORIGINS: {
    type: 'string',
    description: 'Comma-separated list of allowed CORS origins',
    sensitive: false,
    default: 'http://localhost:3000',
    environments: ['development', 'test', 'staging', 'production']
  }
};

// Validation functions
class SecretValidator {
  static validateSecret(name, value, environment) {
    const definition = SECRET_DEFINITIONS[name];

    if (!definition) {
      console.warn(`No definition found for secret: ${name}`);
      return { valid: true, warning: 'No validation definition' };
    }

    // Check if secret should exist in this environment
    if (!definition.environments.includes(environment)) {
      return { 
        valid: false, 
        error: `Secret ${name} should not be used in ${environment} environment` 
      };
    }

    const errors = [];
    const warnings = [];

    // Type validation
    if (definition.type === 'number') {
      const numValue = Number(value);
      if (isNaN(numValue)) {
        errors.push(`Secret ${name} must be a number`);
      } else {
        if (definition.min !== undefined && numValue < definition.min) {
          errors.push(`Secret ${name} must be at least ${definition.min}`);
        }
        if (definition.max !== undefined && numValue > definition.max) {
          errors.push(`Secret ${name} must be at most ${definition.max}`);
        }
      }
    }

    // String validation
    if (definition.type === 'string') {
      if (definition.minLength && value.length < definition.minLength) {
        errors.push(`Secret ${name} must be at least ${definition.minLength} characters`);
      }
      if (definition.maxLength && value.length > definition.maxLength) {
        errors.push(`Secret ${name} must be at most ${definition.maxLength} characters`);
      }
      if (definition.pattern && !definition.pattern.test(value)) {
        errors.push(`Secret ${name} does not match required pattern`);
      }
    }

    // Check for placeholder values in production
    if (environment === 'production') {
      const placeholders = [
        'change-in-production',
        'placeholder',
        'example',
        'CANARY',
        'test-',
        'dev-'
      ];

      const isPlaceholder = placeholders.some(placeholder => 
        value.toLowerCase().includes(placeholder.toLowerCase())
      );

      if (isPlaceholder) {
        errors.push(`Production secret ${name} contains placeholder value`);
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings
    };
  }

  static validateAllSecrets(secrets, environment) {
    const results = {};
    const allValid = Object.keys(secrets).every(name => {
      const result = this.validateSecret(name, secrets[name], environment);
      results[name] = result;
      return result.valid;
    });

    return {
      allValid,
      results
    };
  }
}

// Configuration loader
function loadSecretConfiguration(environment) {
  const config = SECRET_CONFIG[environment] || SECRET_CONFIG.development;

  // Add environment-specific overrides
  if (process.env.SECRET_PROVIDER) {
    config.provider = process.env.SECRET_PROVIDER;
  }

  if (process.env.SECRET_ENCRYPTION_KEY) {
    config.encryptionKey = process.env.SECRET_ENCRYPTION_KEY;
  }

  return config;
}

// Generate .env.example file
function generateEnvExample() {
  let example = '# Environment Variables Configuration\n';
  example += '# DO NOT commit actual values to version control\n\n';

  for (const [name, definition] of Object.entries(SECRET_DEFINITIONS)) {
    example += `# ${definition.description}\n`;
    example += `# Type: ${definition.type}`;

    if (definition.pattern) {
      example += `, Pattern: ${definition.pattern.toString()}`;
    }

    if (definition.minLength) {
      example += `, Min Length: ${definition.minLength}`;
    }

    if (definition.maxLength) {
      example += `, Max Length: ${definition.maxLength}`;
    }

    if (definition.default !== undefined) {
      example += `\n# Default: ${definition.default}`;
    }

    if (definition.sensitive) {
      example += '\n# SENSITIVE: This value is confidential\n';
    }

    example += `${name}=`;

    if (definition.sensitive && definition.default) {
      example += `<${definition.description.toLowerCase().replace(/\s+/g, '-')}>`;
    } else if (definition.default) {
      example += definition.default;
    } else {
      example += 'REQUIRED';
    }

    example += '\n\n';
  }

  return example;
}

// Check for security issues
function securityAudit() {
  const issues = [];
  const env = process.env.NODE_ENV || 'development';

  // Check for .env files in git
  const gitignorePath = path.join(process.cwd(), '.gitignore');
  if (fs.existsSync(gitignorePath)) {
    const gitignore = fs.readFileSync(gitignorePath, 'utf8');
    if (!gitignore.includes('.env') && !gitignore.includes('.env*')) {
      issues.push('.env files not excluded in .gitignore');
    }
  }

  // Check for hardcoded secrets in JS files
  const jsFiles = fs.readdirSync(process.cwd())
    .filter(file => file.endsWith('.js') && !file.includes('secret'));

  const hardcodedPatterns = [
    /(password|secret|key|token)\s*[:=]\s*["'][^"']{4,}["']/gi,
    /process\.env\.\w+\s*\|\|\s*["'][^"']{4,}["']/g
  ];

  jsFiles.forEach(file => {
    try {
      const content = fs.readFileSync(path.join(process.cwd(), file), 'utf8');

      hardcodedPatterns.forEach(pattern => {
        const matches = content.match(pattern);
        if (matches) {
          matches.forEach(match => {
            issues.push(`Potential hardcoded secret in ${file}: ${match.substring(0, 50)}...`);
          });
        }
      });
    } catch (error) {
      // Skip files we can't read
    }
  });

  return issues;
}

module.exports = {
  SECRET_CONFIG,
  SECRET_DEFINITIONS,
  SecretValidator,
  loadSecretConfiguration,
  generateEnvExample,
  securityAudit
};

