/**
 * AWS Secrets Manager Integration
 * Production-grade secrets management
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      ...options
    });

    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes cache
    this.initialized = false;
  }

  /**
   * Get secret value from AWS Secrets Manager with caching
   * @param {string} secretId - Secret identifier
   * @param {boolean} forceRefresh - Bypass cache
   * @returns {Promise<string>} Secret value
   */
  async getSecret(secretId, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretId)) {
      const cached = this.cache.get(secretId);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretId })
      );

      let secretValue;
      if ('SecretString' in response) {
        secretValue = response.SecretString;
      } else {
        // Binary secrets are base64 encoded
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('utf-8');
      }

      // Cache the result
      this.cache.set(secretId, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretId}:`, error);

      // Fallback to environment variable for development
      const envFallback = process.env[secretId];
      if (envFallback) {
        console.warn(`Using environment variable fallback for ${secretId}`);
        return envFallback;
      }

      throw new Error(`Secret ${secretId} not available and no fallback found`);
    }
  }

  /**
   * Get secret as JSON object
   * @param {string} secretId - Secret identifier
   * @returns {Promise<Object>} Parsed secret object
   */
  async getSecretJSON(secretId) {
    const secretValue = await this.getSecret(secretId);
    try {
      return JSON.parse(secretValue);
    } catch (error) {
      throw new Error(`Secret ${secretId} is not valid JSON`);
    }
  }

  /**
   * Get multiple secrets in parallel
   * @param {string[]} secretIds - Array of secret identifiers
   * @returns {Promise<Object>} Object with secretId: value pairs
   */
  async getSecrets(secretIds) {
    const promises = secretIds.map(id => this.getSecret(id));
    const results = await Promise.allSettled(promises);

    const secrets = {};
    results.forEach((result, index) => {
      if (result.status === 'fulfilled') {
        secrets[secretIds[index]] = result.value;
      } else {
        console.error(`Failed to load secret ${secretIds[index]}:`, result.reason);
        secrets[secretIds[index]] = null;
      }
    });

    return secrets;
  }

  /**
   * Rotate secret (requires appropriate IAM permissions)
   * @param {string} secretId - Secret identifier
   * @param {string} newValue - New secret value
