/**
 * Environment-based secrets loader
 * Supports multiple secret management backends
 */
class SecretsLoader {
  constructor() {
    this.secrets = {};
    this.backend = this.determineBackend();
  }

  determineBackend() {
    // Determine which secrets backend to use based on environment
    if (process.env.AWS_REGION && process.env.NODE_ENV === 'production') {
      return 'aws-secrets-manager';
    } else if (process.env.HASHICORP_VAULT_ADDR) {
      return 'vault';
    } else if (process.env.GOOGLE_SECRETS_PROJECT) {
      return 'gcp-secrets';
    } else {
      return 'env-files'; // Fallback to environment variables
    }
  }

  async loadSecrets(requiredSecrets = {}) {
    const backend = this.determineBackend();

    switch (backend) {
      case 'aws-secrets-manager':
        await this.loadFromAWSSecretsManager(requiredSecrets);
        break;
      case 'vault':
        await this.loadFromVault(requiredSecrets);
        break;
      case 'gcp-secrets':
        await this.loadFromGCPSecrets(requiredSecrets);
        break;
      default:
        await this.loadFromEnvFiles(requiredSecrets);
    }

    this.validateSecrets(requiredSecrets);
    return this.secrets;
  }

  async loadFromAWSSecretsManager(requiredSecrets) {
    const secretsManager = new SecretsManager();

    for (const [key, config] of Object.entries(requiredSecrets)) {
      try {
        const secretId = config.secretId || key;
        const secretValue = await secretsManager.getSecret(secretId);

        if (config.json) {
          this.secrets[key] = JSON.parse(secretValue);
        } else {
          this.secrets[key] = secretValue;
        }

        console.log(`✅ Loaded secret: ${key}`);
      } catch (error) {
        console.error(`❌ Failed to load secret ${key}:`, error.message);

        // Use default if available
        if (config.default !== undefined) {
          console.warn(`Using default value for ${key}`);
          this.secrets[key] = config.default;
        } else {
          throw new Error(`Required secret ${key} not available`);
        }
      }
    }
  }

  async loadFromEnvFiles(requiredSecrets) {
    // Development fallback using environment variables
    for (const [key, config] of Object.entries(requiredSecrets)) {
      const envKey = config.envKey || key;

      if (process.env[envKey]) {
        if (config.json) {
          try {
            this.secrets[key] = JSON.parse(process.env[envKey]);
          } catch (error) {
            throw new Error(`Environment variable ${envKey} is not valid JSON`);
          }
        } else {
          this.secrets[key] = process.env[envKey];
        }
        console.log(`✅ Loaded from env: ${key}`);
      } else if (config.default !== undefined) {
        console.warn(`Using default value for ${key}`);
        this.secrets[key] = config.default;
      } else {
        throw new Error(`Required environment variable ${envKey} not set`);
      }
    }
  }

  validateSecrets(requiredSecrets) {
    const errors = [];

    for (const [key, config] of Object.entries(requiredSecrets)) {
      const value = this.secrets[key];

      // Check if secret exists
      if (value === undefined || value === null) {
        errors.push(`Missing required secret: ${key}`);
        continue;
      }

      // Validate format if regex provided
      if (config.validate && config.validate.regex) {
        const regex = new RegExp(config.validate.regex);
        if (!regex.test(value)) {
          errors.push(`Secret ${key} does not match required format: ${config.validate.regex}`);
        }
      }

      // Validate length if specified
      if (config.validate && config.validate.minLength && value.length < config.validate.minLength) {
        errors.push(`Secret ${key} is too short (min ${config.validate.minLength} chars)`);
      }

      // Validate it's not a default/placeholder value
      if (config.validate && config.validate.noDefaults) {
        const defaultPatterns = ['changeme', 'secret', 'password', 'key', 'token', 'default'];
        const lowerValue = value.toLowerCase();
        if (defaultPatterns.some(pattern => lowerValue.includes(pattern))) {
          errors.push(`Secret ${key} appears to be a default/placeholder value`);
        }
      }
    }

    if (errors.length > 0) {
      throw new Error(`Secret validation failed:\n${errors.join('\n')}`);
    }
  }

  getSecrets() {
    return this.secrets;
  }

  getSecret(key) {
    return this.secrets[key];
  }
}

