class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  /**
   * Initialize and load all secrets
   */
  async initialize() {
    if (this.initialized) {
      console.warn('SecretsManager already initialized');
      return;
    }

    console.log('🔐 Loading application secrets...');

    try {
      // Determine secrets backend
      const backend = this.determineBackend();
      console.log(`Using secrets backend: ${backend}`);

      switch (backend) {
        case 'aws-secrets-manager':
          await this.loadFromAWSSecretsManager();
          break;
        case 'azure-keyvault':
          await this.loadFromAzureKeyVault();
          break;
        case 'gcp-secrets':
          await this.loadFromGCPSecrets();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        default:
          await this.loadFromEnvironment();
      }

      this.validateAllSecrets();
      this.initialized = true;
      console.log('✅ Secrets loaded successfully');

    } catch (error) {
      console.error('❌ Failed to load secrets:', error);
      process.exit(1);
    }
  }

  determineBackend() {
    // Production: Use cloud secrets manager
    if (process.env.NODE_ENV === 'production') {
      if (process.env.AWS_REGION) return 'aws-secrets-manager';
      if (process.env.AZURE_KEYVAULT_URI) return 'azure-keyvault';
      if (process.env.GCP_PROJECT) return 'gcp-secrets';
      if (process.env.VAULT_ADDR) return 'vault';
    }

    // Development/Testing: Use environment variables
    return 'environment';
  }

  async loadFromAWSSecretsManager() {
    try {
      const { SecretsManagerClient, GetSecretValueCommand } = await import('@aws-sdk/client-secrets-manager');

      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      for (const [key, config] of Object.entries(SECRETS_CONFIG)) {
        const secretId = config.secretId || key;

        try {
          const response = await client.send(
            new GetSecretValueCommand({ SecretId: secretId })
          );

          let secretValue = response.SecretString;
          if (config.json) {
            this.secrets.set(key, JSON.parse(secretValue));
          } else {
            this.secrets.set(key, secretValue);
          }

          console.log(`✅ Loaded ${key} from AWS Secrets Manager`);
        } catch (error) {
          console.warn(`⚠️  ${key} not found in AWS Secrets Manager, checking environment`);
          this.loadFromEnvironmentForKey(key, config);
        }
      }
    } catch (error) {
      console.error('AWS Secrets Manager unavailable:', error.message);
      await this.loadFromEnvironment();
    }
  }

  async loadFromEnvironment() {
    console.log('Loading secrets from environment variables...');

    for (const [key, config] of Object.entries(SECRETS_CONFIG)) {
      this.loadFromEnvironmentForKey(key, config);
    }
  }

  loadFromEnvironmentForKey(key, config) {
    const envKey = config.envKey || key;
    const envValue = process.env[envKey];

    if (envValue) {
      if (config.json) {
        try {
          this.secrets.set(key, JSON.parse(envValue));
          console.log(`✅ Loaded ${key} from environment (JSON)`);
        } catch (error) {
          console.error(`❌ ${key}: Invalid JSON in environment variable`);
          this.fallbackToDefault(key, config);
        }
      } else {
        this.secrets.set(key, envValue);
        console.log(`✅ Loaded ${key} from environment`);
      }
    } else {
      this.fallbackToDefault(key, config);
    }
  }

  fallbackToDefault(key, config) {
    if (config.default !== undefined) {
      this.secrets.set(key, config.default);

      if (process.env.NODE_ENV === 'production') {
        console.error(`❌ PRODUCTION ERROR: ${key} using default value!`);
        process.exit(1);
      } else {
        console.warn(`⚠️  ${key}: Using development default`);
      }
    } else {
      console.error(`❌ CRITICAL: ${key} not available and no default provided`);
      process.exit(1);
    }
  }

  validateAllSecrets() {
    console.log('🔍 Validating secrets...');

    for (const [key, config] of Object.entries(SECRETS_CONFIG)) {
      const value = this.secrets.get(key);

      if (value === undefined || value === null) {
        throw new Error(`Secret ${key} is missing`);
      }

      // String validation
      if (typeof value === 'string') {
        if (config.validate?.minLength && value.length < config.validate.minLength) {
          throw new Error(`Secret ${key} is too short (min ${config.validate.minLength} chars)`);
        }

        if (config.validate?.regex) {
          const regex = new RegExp(config.validate.regex);
          if (!regex.test(value)) {
            throw new Error(`Secret ${key} does not match required format`);
          }
        }

        if (config.validate?.noDefaults) {
          const forbidden = ['changeme', 'secret', 'password', 'default', 'test', 'example'];
          const lowerValue = value.toLowerCase();
          if (forbidden.some(word => lowerValue.includes(word))) {
            throw new Error(`Secret ${key} appears to be a default/placeholder value`);
          }
        }
      }

      // JSON object validation
      if (config.json && typeof value === 'object') {
        if (config.validate?.requiredFields) {
          config.validate.requiredFields.forEach(field => {
            if (!value[field]) {
              throw new Error(`Secret ${key} missing required field: ${field}`);
            }
          });
        }
      }
    }

    console.log('✅ All secrets validated');
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    const value = this.secrets.get(key);
    if (value === undefined) {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  getAll() {
    return Object.fromEntries(this.secrets);
  }

  // Security: Never log actual secrets, only metadata
  logSecretsMetadata() {
    console.log('\n📊 Secrets Loaded:');
    console.log('════════════════════════════════════');

    for (const [key, config] of Object.entries(SECRETS_CONFIG)) {
      const value = this.secrets.get(key);
      const type = config.json ? 'JSON Object' : 'String';
      const length = typeof value === 'string' ? value.length : 'N/A';

      console.log(`${key}:`);
      console.log(`  Type: ${type}`);
      console.log(`  Description: ${config.description}`);

      if (typeof value === 'string') {
        console.log(`  Length: ${length} chars`);
        console.log(`  Preview: ${value.substring(0, 3)}...${value.substring(value.length - 3)}`);
      } else if (config.json) {
        console.log(`  Keys: ${Object.keys(value).join(', ')}`);
      }

      console.log('');
    }

    console.log('════════════════════════════════════\n');
  }
}

