// Initialize secrets manager
const secretsManager = new SecretsManager();

// Initialize Express app
const app = express();

// Async initialization
async function initializeApplication() {
  try {
    // Load secrets first
    await secretsManager.initialize();
    secretsManager.logSecretsMetadata();

    // Get secrets
    const secrets = secretsManager.getAll();

    // Set configuration from secrets
    const PORT = process.env.PORT || 3000;
    const NODE_ENV = process.env.NODE_ENV || 'development';
    const JWT_SECRET = secrets.JWT_SECRET;

    // Validate production requirements
    if (NODE_ENV === 'production') {
      if (!JWT_SECRET || JWT_SECRET.includes('development')) {
        throw new Error('Production JWT_SECRET must be a strong secret, not a development value');
      }
    }

    // ========================
    // SECURITY MIDDLEWARE STACK
    // ========================

    // Helmet for security headers
    app.use(helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          scriptSrc: ["'self'"],
          imgSrc: ["'self'", "data:", "https:"],
          connectSrc: ["'self'"],
          fontSrc: ["'self'", "https:"],
          objectSrc: ["'none'"],
          mediaSrc: ["'self'"]
        }
      },
      hsts: NODE_ENV === 'production' ? {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
      } : false
    }));

    // Rate limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000,
      max: NODE_ENV === 'production' ? 100 : 1000,
      standardHeaders: true,
      legacyHeaders: false,
      message: 'Too many requests from this IP, please try again later.'
    });

    app.use(limiter);

    // CORS configuration
    const allowedOrigins = process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',') 
      : NODE_ENV === 'production' ? [] : ['http://localhost:3000'];

    app.use(cors({
      origin: (origin, callback) => {
        if (!origin || NODE_ENV !== 'production') {
          return callback(null, true);
        }

        if (allowedOrigins.includes(origin)) {
          callback(null, true);
        } else {
          callback(new Error(`Origin ${origin} not allowed by CORS policy`));
        }
      },
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
    }));

    // Body parsing with limits
    app.use(express.json({
      limit: '1mb',
      verify: (req, res, buf) => {
        const contentType = req.headers['content-type'];
        if (contentType && !contentType.includes('application/json')) {
          throw new Error('Invalid content type');
        }
      }
    }));

    app.use(express.urlencoded({
      extended: false,
      limit: '1mb'
    }));

    // ========================
    // LOGGING CONFIGURATION
    // ========================

    const logger = winston.createLogger({
      level: NODE_ENV === 'development' ? 'debug' : 'info',
      format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
      ),
      transports: [
        new winston.transports.File({ 
          filename: 'logs/error.log', 
          level: 'error',
          // Don't log secrets in log files
          format: winston.format((info) => {
            // Sanitize logs to remove any secret values
            const sanitizedInfo = { ...info };
            Object.keys(secrets).forEach(key => {
              if (sanitizedInfo.message && typeof sanitizedInfo.message === 'string') {
                sanitizedInfo.message = sanitizedInfo.message.replace(
                  new RegExp(secrets[key], 'g'), 
                  '[REDACTED_SECRET]'
                );
              }
            });
            return sanitizedInfo;
          })()
        }),
        new winston.transports.File({ filename: 'logs/combined.log' }),
        ...(NODE_ENV === 'development' ? [new winston.transports.Console({
          format: winston.format.combine(
            winston.format.colorize(),
            winston.format.simple()
          )
        })] : [])
      ]
    });

    // Enhanced request logging (sanitized)
    app.use(morgan('combined', {
      stream: {
        write: (message) => {
          // Sanitize logs to remove any secret values
          let sanitizedMessage = message;
          Object.values(secrets).forEach(secret => {
            if (typeof secret === 'string') {
              sanitizedMessage = sanitizedMessage.replace(
                new RegExp(secret, 'g'), 
                '[REDACTED_SECRET]'
              );
            }
          });
          logger.info(sanitizedMessage.trim());
        }
      },
      skip: (req) => req.url === '/health'
    }));

    // ========================
    // AUTHENTICATION MIDDLEWARE
    // ========================

    const jwt = require('jsonwebtoken');

    const authenticateToken = (req, res, next) => {
      const authHeader = req.headers['authorization'];
      const token = authHeader && authHeader.split(' ')[1];

      if (!token) {
        logger.warn('SECURITY_EVENT', {
          event: 'MISSING_AUTH_TOKEN',
          ip: req.ip,
          url: req.url
        });
        return res.status(401).json({ 
          error: 'Authentication required',
          code: 'AUTH_REQUIRED'
        });
      }

      jwt.verify(token, JWT_SECRET, (err, user) => {
        if (err) {
          logger.warn('SECURITY_EVENT', {
            event: 'INVALID_AUTH_TOKEN',
            ip: req.ip,
            url: req.url,
            error: err.message
          });
          return res.status(403).json({ 
            error: 'Invalid or expired token',
            code: 'INVALID_TOKEN'
          });
        }

        req.user = user;
        next();
      });
    };

    // ========================
    // HEALTH CHECK ENDPOINT
    // ========================

    app.get('/health', [
      query('detailed').optional().isBoolean().toBoolean()
    ], (req, res) => {
      const isDetailed = req.query.detailed;

      const healthStatus = {
        status: 'healthy',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memoryUsage: `${Math.round(process.memoryUsage().heapUsed / 1024 / 1024)}MB`,
        nodeVersion: process.version.slice(1)
      };

      if (isDetailed) {
        healthStatus.environment = NODE_ENV;
        healthStatus.pid = process.pid;
        healthStatus.secretsLoaded = Object.keys(secrets).length;
        healthStatus.secretsBackend = secretsManager.determineBackend();
      }

      res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
      res.setHeader('Pragma', 'no-cache');
      res.setHeader('Expires', '0');
      res.setHeader('X-Secrets-Backend', secretsManager.determineBackend());

      res.json(healthStatus);
    });

    // ========================
    // SECRETS MANAGEMENT ENDPOINT (ADMIN ONLY)
    // ========================

    app.get('/admin/secrets-status', authenticateToken, (req, res) => {
      // Only allow admin users
      if (req.user.role !== 'admin') {
        return res.status(403).json({ error: 'Admin access required' });
      }

      const status = {
        backend: secretsManager.determineBackend(),
        loadedSecrets: Object.keys(secrets).length,
        environment: NODE_ENV,
        validation: 'PASSED',
        timestamp: new Date().toISOString()
      };

      // Never expose actual secret values
      res.json(status);
    });

    // ========================
    // START SERVER
    // ========================

    app.disable('x-powered-by');

    const server = app.listen(PORT, '0.0.0.0', () => {
      logger.info(`🚀 Server running on port ${PORT} in ${NODE_ENV} mode`);
      logger.info(`🔐 Secrets backend: ${secretsManager.determineBackend()}`);
      logger.info(`📊 Loaded ${Object.keys(secrets).length} secrets`);

      if (NODE_ENV === 'development') {
        console.warn('\n⚠️  DEVELOPMENT MODE WARNING ⚠️');
        console.warn('Using development/default secrets');
        console.warn('DO NOT use in production!\n');
      }
    });

    // Graceful shutdown
    const shutdown = async () => {
      logger.info('Shutting down gracefully...');

      // Rotate secrets on shutdown in production
      if (NODE_ENV === 'production') {
        logger.info('Initiating secret rotation check...');
        // Implement secret rotation logic here
      }

      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    };

    process.on('SIGTERM', shutdown);
    process.on('SIGINT', shutdown);

    return { app, server, secretsManager };

  } catch (error) {
    console.error('❌ Application initialization failed:', error);
    process.exit(1);
  }
}

// Start the application
initializeApplication().then(({ app }) => {
