// Secure Express.js application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// Security middleware setup
app.use(helmet()); // Set security headers

// Enable CORS with specific origin (configure based on your needs)
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3001',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter); // Apply to all routes under /api

// Input validation middleware
const validateUserQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters
  if (limit && !/^\d+$/.test(limit)) {
    return res.status(400).json({ error: 'Limit must be a positive integer' });
  }

  if (offset && !/^\d+$/.test(offset)) {
    return res.status(400).json({ error: 'Offset must be a positive integer' });
  }

  // Set default values and constraints
  req.query.limit = Math.min(parseInt(limit) || 10, 100); // Max 100 items
  req.query.offset = parseInt(offset) || 0;

  next();
};

// Improved health endpoint with security considerations
app.get('/health', (req, res) => {
  // Don't expose detailed system information
  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Secure users endpoint with input validation
app.get('/users', validateUserQuery, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination (even with hardcoded data for pattern)
  const limit = req.query.limit;
  const offset = req.query.offset;

  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit,
      offset
    }
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack); // Log error for monitoring

  // Don't leak stack trace to client
  res.status(err.status || 500).json({
    error: 'An unexpected error occurred',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Read port from environment variable
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});

module.exports = app;

/**
 * Security Configuration
 * Centralizes security settings for the application
 */

module.exports = {
  // Helmet.js configuration
