/**
 * Comprehensive Input Validation Middleware
 * Implements multiple validation strategies for different security concerns
 */

const { validationPatterns } = require('./security-config');

class ValidationMiddleware {
  /**
   * Validate and sanitize query parameters
   * @param {Object} schema - Validation schema for query parameters
   */
  static validateQueryParams(schema) {
    return (req, res, next) => {
      try {
        const errors = [];

        for (const [param, rules] of Object.entries(schema)) {
          const value = req.query[param];

          if (rules.required && (value === undefined || value === null || value === '')) {
            errors.push(`${param} is required`);
            continue;
          }

          if (value !== undefined && value !== null && value !== '') {
            // Type validation
            if (rules.type) {
              const typeError = this.validateType(param, value, rules.type);
              if (typeError) errors.push(typeError);
            }

            // Pattern validation
            if (rules.pattern) {
              const patternError = this.validatePattern(param, value, rules.pattern);
              if (patternError) errors.push(patternError);
            }

            // Custom validation
            if (rules.validate) {
              const customError = rules.validate(value);
              if (customError) errors.push(customError);
            }

            // Sanitize values
            if (rules.sanitize) {
              req.query[param] = this.sanitizeValue(value, rules.sanitize);
            }

            // Range validation for numbers
            if (rules.min !== undefined && rules.type === 'number') {
              const numValue = Number(value);
              if (numValue < rules.min) {
                errors.push(`${param} must be at least ${rules.min}`);
              }
            }

            if (rules.max !== undefined && rules.type === 'number') {
              const numValue = Number(value);
              if (numValue > rules.max) {
                errors.push(`${param} must be at most ${rules.max}`);
              }
            }
          }
        }

        if (errors.length > 0) {
          return res.status(400).json({
            error: 'Validation failed',
            details: errors,
          });
        }

        next();
      } catch (error) {
        console.error('Validation error:', error);
        res.status(500).json({ error: 'Validation error occurred' });
      }
    };
  }

  /**
   * Validate request body
   * @param {Object} schema - Validation schema for body
   */
  static validateBody(schema) {
    return (req, res, next) => {
      try {
        const errors = [];

        for (const [field, rules] of Object.entries(schema)) {
          const value = req.body[field];

          if (rules.required && (value === undefined || value === null || value === '')) {
            errors.push(`${field} is required`);
            continue;
          }

          if (value !== undefined && value !== null && value !== '') {
            // Type validation
            if (rules.type) {
              const typeError = this.validateType(field, value, rules.type);
              if (typeError) errors.push(typeError);
            }

            // XSS prevention
            if (rules.sanitizeHtml) {
              req.body[field] = this.sanitizeHtml(value);
            }

            // Length validation for strings
            if (rules.minLength && typeof value === 'string') {
              if (value.length < rules.minLength) {
                errors.push(`${field} must be at least ${rules.minLength} characters`);
              }
            }

            if (rules.maxLength && typeof value === 'string') {
              if (value.length > rules.maxLength) {
                errors.push(`${field} must be at most ${rules.maxLength} characters`);
              }
            }
          }
        }

        if (errors.length > 0) {
          return res.status(400).json({
            error: 'Validation failed',
            details: errors,
          });
        }

        next();
      } catch (error) {
        console.error('Validation error:', error);
        res.status(500).json({ error: 'Validation error occurred' });
      }
    };
  }

  /**
   * SQL Injection prevention middleware
   */
  static preventSqlInjection() {
    return (req, res, next) => {
      const sqlKeywords = [
        'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'DROP', 'UNION', 'OR', 'AND',
        'EXEC', 'EXECUTE', 'TRUNCATE', 'ALTER', 'CREATE', 'DATABASE', 'TABLE',
        'FROM', 'WHERE', 'JOIN', 'HAVING', 'GROUP BY', 'ORDER BY'
      ];

      const checkForSql = (obj) => {
        if (typeof obj === 'string') {
          const upperStr = obj.toUpperCase();
          for (const keyword of sqlKeywords) {
            if (upperStr.includes(keyword) && 
                upperStr.includes('(') && 
                upperStr.includes(')')) {
              return true;
            }
          }
        } else if (typeof obj === 'object' && obj !== null) {
          for (const key in obj) {
            if (checkForSql(obj[key])) return true;
          }
        }
        return false;
      };

      if (checkForSql(req.query) || checkForSql(req.body) || checkForSql(req.params)) {
        return res.status(400).json({ 
          error: 'Invalid input detected' 
        });
      }

      next();
    };
  }

  /**
   * Validate parameter type
   */
  static validateType(field, value, expectedType) {
    switch (expectedType) {
      case 'number':
        if (isNaN(Number(value))) return `${field} must be a number`;
        break;
      case 'integer':
        if (!Number.isInteger(Number(value))) return `${field} must be an integer`;
        break;
      case 'string':
        if (typeof value !== 'string') return `${field} must be a string`;
        break;
      case 'boolean':
        if (value !== 'true' && value !== 'false' && value !== true && value !== false) {
          return `${field} must be a boolean`;
        }
        break;
      case 'email':
        if (!validationPatterns.email.test(value)) return `${field} must be a valid email`;
        break;
      case 'uuid':
        if (!validationPatterns.uuid.test(value)) return `${field} must be a valid UUID`;
        break;
      case 'alphanumeric':
        if (!validationPatterns.alphanumeric.test(value)) {
          return `${field} must contain only alphanumeric characters`;
        }
        break;
    }
    return null;
  }

  /**
   * Validate against pattern
   */
  static validatePattern(field, value, pattern) {
    if (!pattern.test(value)) {
      return `${field} contains invalid characters`;
    }
    return null;
  }

  /**
   * Sanitize value based on type
   */
  static sanitizeValue(value, sanitizeType) {
    switch (sanitizeType) {
      case 'trim':
        return value.trim();
      case 'lowercase':
        return value.toLowerCase();
      case 'uppercase':
        return value.toUpperCase();
      case 'escape':
        return this.escapeHtml(value);
      case 'integer':
        return parseInt(value, 10);
      case 'float':
        return parseFloat(value);
      default:
        return value;
    }
  }

  /**
   * Escape HTML characters to prevent XSS
   */
  static escapeHtml(text) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    };
    return String(text).replace(/[&<>"']/g, m => map[m]);
  }

  /**
   * Basic HTML sanitization
   */
  static sanitizeHtml(html) {
    return String(html)
      .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
      .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, '')
      .replace(/javascript:/gi, '')
      .replace(/on\w+\s*=/gi, '');
  }
}

module.exports = ValidationMiddleware;

