/**
 * Secure Environment Configuration Loader
 * Implements multiple strategies for secret management
 * Prefers secret managers over .env files for production
 */

const fs = require('fs');
const path = require('path');

class EnvironmentConfig {
  constructor() {
    this.config = {};
    this.loadedFrom = [];
    this.requiredSecrets = [];
    this.secretsMask = {};
  }

  /**
   * Initialize environment configuration
   * @param {Object} options Configuration options
   */
  async initialize(options = {}) {
    const {
      validateRequired = true,
      loadFromEnvFile = true,
      loadFromSecretManager = false,
      secretManagerConfig = {},
      environment = process.env.NODE_ENV || 'development'
    } = options;

    this.environment = environment;

    // Load from system environment first (highest priority)
    this.loadFromSystemEnv();

    // Load from .env file if enabled (development convenience)
    if (loadFromEnvFile && environment !== 'production') {
      await this.loadFromEnvFile();
    }

    // Load from secret manager if configured (production preference)
    if (loadFromSecretManager) {
      await this.loadFromSecretManager(secretManagerConfig);
    }

    // Validate required secrets
    if (validateRequired) {
      this.validateRequiredSecrets();
    }

    // Apply default values for missing configuration
    this.applyDefaults();

    // Mask sensitive values for logging
    this.maskSensitiveValues();

    return this.config;
  }

  /**
   * Load from system environment variables
   */
  loadFromSystemEnv() {
    console.log('[Env] Loading from system environment variables');

    // Copy all process.env to config
    this.config = { ...process.env };
    this.loadedFrom.push('system-environment');
  }

  /**
   * Load from .env file (development only)
   */
  async loadFromEnvFile() {
    const envFile = `.env.${this.environment}`;
    const defaultEnvFile = '.env';

    try {
      // Check for environment-specific .env file first
      if (fs.existsSync(envFile)) {
