  });

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({
      error: 'Not Found',
      message: `Cannot ${req.method} ${req.originalUrl}`,
      requestId: req.id || Date.now().toString(36)
    });
  });

  // Start server
  const PORT = env.get('PORT', 3000);
  const server = app.listen(PORT, () => {
    console.log(`[Server] Secure application running on port ${PORT}`);
    console.log(`[Server] Environment: ${env.get('NODE_ENV')}`);
    console.log(`[Server] Health endpoints: http://localhost:${PORT}/health`);
    console.log(`[Server] API endpoints: http://localhost:${PORT}/api/*`);
