class SecretsManager {
  constructor() {
    this.secretsCache = {};
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.secretsCache[secretName]) {
      const cached = this.secretsCache[secretName];
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    let secretValue;

    // Use AWS Secrets Manager in production
    if (process.env.NODE_ENV === 'production') {
      const secretsManager = new AWS.SecretsManager();
      const data = await secretsManager.getSecretValue({ 
        SecretId: secretName 
      }).promise();
      secretValue = JSON.parse(data.SecretString);
    } 
    // Use environment variables in other environments
    else {
      // Map secret names to environment variables
      const envVarMap = {
        'database/url': process.env.DATABASE_URL,
        'aws/credentials': {
