        'stripe/key': process.env.STRIPE_SECRET_KEY,
        'anthropic/api-key': process.env.ANTHROPIC_API_KEY
      };

      secretValue = envVarMap[secretName];

      if (!secretValue) {
        throw new Error(`Secret ${secretName} not found in environment variables`);
      }
    }

    // Cache the result
    this.secretsCache[secretName] = {
      value: secretValue,
      timestamp: Date.now()
    };

    return secretValue;
  }

  invalidateCache(secretName) {
    delete this.secretsCache[secretName];
  }
}

