const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-secrets-manager');
const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loaded = false;
  }

  async init() {
    if (this.loaded) return this.secrets;

    // Try AWS Secrets Manager first
    try {
