      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN
    };
  }

  validateSecrets() {
    const required = ['jwtSecret', 'databaseUrl'];

    for (const secret of required) {
      if (!this.secrets[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }

      if (secret === 'jwtSecret' && this.secrets.jwtSecret.length < 32) {
        throw new Error('JWT_SECRET must be at least 32 characters');
      }
    }
  }

  // Rotate a specific secret
  async rotateSecret(secretName) {
    const newSecret = crypto.randomBytes(32).toString('hex');

    // Update in AWS Secrets Manager
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const currentSecrets = { ...this.secrets, [secretName]: newSecret };

    const command = new UpdateSecretCommand({
      SecretId: process.env.SECRETS_NAME || 'myapp/production',
      SecretString: JSON.stringify(currentSecrets)
    });

    await client.send(command);

    // Update local cache
    this.secrets[secretName] = newSecret;

    return newSecret;
  }
}

