// Secure Express.js Application
// Addressing OWASP Top 10 Security Concerns

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const app = express();

// ============= SECURITY MIDDLEWARE =============

// 1. Security Headers (Helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xssFilter: true,
  hidePoweredBy: true,
  frameguard: { action: 'deny' }
}));

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 3. CORS Configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' ? ['https://yourdomain.com'] : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 4. Request Parsing Security
app.use(express.json({
  limit: '1mb', // Prevent large payload attacks
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf); // Validate JSON
    } catch (e) {
      res.status(400).json({ error: 'Invalid JSON payload' });
      throw new Error('Invalid JSON');
    }
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: '1mb',
  parameterLimit: 10 // Limit number of parameters
}));

// 5. Request Logging (Security-focused)
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks
}));

// 6. Input Validation Middleware
const validateUserQuery = (req, res, next) => {
  // Validate query parameters
  const { limit, offset } = req.query;

  if (limit && (!Number.isInteger(Number(limit)) || Number(limit) > 100 || Number(limit) < 1)) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be between 1 and 100.' 
    });
  }

  if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
    return res.status(400).json({ 
      error: 'Invalid offset parameter. Must be a positive integer.' 
    });
  }

  next();
};

// 7. Authentication Middleware (Example)
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // In a real application, verify JWT token here
  // Example: jwt.verify(token, process.env.JWT_SECRET)

  next(); // For demo purposes
};

// ============= ROUTES WITH SECURITY =============

// Public health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Protected users endpoint with input validation
app.get('/users', authenticateToken, validateUserQuery, (req, res) => {
  // Apply query limits for security
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);
  const offset = parseInt(req.query.offset) || 0;

  // Sanitize output to prevent data leakage
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'a***@example.com', // Mask email for security
      createdAt: '2024-01-01T00:00:00.000Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'b***@example.com', // Mask email for security
      createdAt: '2024-01-01T00:00:00.000Z'
    },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
});

// Example POST endpoint with validation
app.post('/users', authenticateToken, (req, res) => {
  const { name, email, password } = req.body;

  // Input validation
  if (!name || name.length < 2 || name.length > 50) {
    return res.status(400).json({ error: 'Name must be between 2 and 50 characters' });
  }

  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'Valid email is required' });
  }

  if (!password || password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  // In real application:
  // 1. Hash password: bcrypt.hash(password, 10)
  // 2. Store in database with parameterized queries

  res.status(201).json({ 
    message: 'User created successfully',
    user: { 
      id: 3, 
      name, 
      email: email.replace(/(?<=.).(?=.*@)/g, '*'), // Mask email
      createdAt: new Date().toISOString() 
    }
  });
});

// ============= ERROR HANDLING =============

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error('Security Alert - Error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// ============= SERVER CONFIGURATION =============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Security check for production
if (process.env.NODE_ENV === 'production') {
  if (!process.env.JWT_SECRET) {
    console.error('SECURITY WARNING: JWT_SECRET environment variable not set!');
    process.exit(1);
  }

  if (!process.env.DATABASE_URL) {
    console.error('SECURITY WARNING: DATABASE_URL environment variable not set!');
    process.exit(1);
  }
}

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Listening on http://${HOST}:${PORT}`);
  console.log('Security features enabled:');
  console.log('- Helmet.js security headers');
  console.log('- Rate limiting');
  console.log('- CORS protection');
  console.log('- Input validation');
  console.log('- Authentication middleware');
});

// Graceful shutdown for security
process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('Received SIGINT, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review Report for app.js
## OWASP Top 10 Security Assessment

### Executive Summary
The original `app.js` file exhibits **multiple critical security vulnerabilities** that could lead to data breaches, unauthorized access, and service disruption. The application lacks basic security controls and follows insecure development patterns.

### Critical Issues Found

#### 1. **Missing Security Headers** (Severity: HIGH)
- **Issue**: No security headers configured
- **Impact**: Vulnerable to XSS, clickjacking, MIME sniffing attacks
- **Fix**: Implement Helmet.js middleware

#### 2. **No Authentication/Authorization** (Severity: CRITICAL)
- **Issue**: All endpoints publicly accessible
- **Impact**: Unauthorized data access and modification
- **Fix**: Implement JWT-based authentication and role-based access control

#### 3. **No Input Validation** (Severity: HIGH)
- **Issue**: No validation of user inputs
- **Impact**: Injection attacks, data corruption, business logic bypass
- **Fix**: Implement express-validator middleware

#### 4. **No Rate Limiting** (Severity: MEDIUM)
- **Issue**: No protection against brute force or DoS attacks
- **Impact**: Service disruption, resource exhaustion
- **Fix**: Implement express-rate-limit middleware

#### 5. **Sensitive Data Exposure** (Severity: HIGH)
- **Issue**: User emails exposed in clear text
- **Impact**: Privacy violation, potential phishing attacks
- **Fix**: Mask sensitive data, implement proper access controls

### OWASP Top 10 Specific Concerns

#### A01:2021 - Broken Access Control
**Vulnerabilities Found:**
- No authentication checks on `/users` endpoint
- No authorization checks
- No session management

**Recommendations:**
```javascript
// Implement authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Access denied' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Implement role-based access control
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};
```

#### A02:2021 - Cryptographic Failures
**Vulnerabilities Found:**
- HTTP only (no HTTPS enforcement)
- No password hashing (if implemented later)
- Sensitive data in environment file (.env.test)

**Recommendations:**
```javascript
// Force HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.headers['x-forwarded-proto'] !== 'https') {
      return res.redirect(`https://${req.headers.host}${req.url}`);
    }
    next();
  });
}

// Secure password hashing with bcrypt
const bcrypt = require('bcrypt');
const saltRounds = 10;

const hashPassword = async (password) => {
  return await bcrypt.hash(password, saltRounds);
};

const verifyPassword = async (password, hash) => {
  return await bcrypt.compare(password, hash);
};
```

#### A03:2021 - Injection
**Vulnerabilities Found:**
- No protection against NoSQL injection
- No protection against SQL injection (if DB added)
- No input sanitization

**Recommendations:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');

// Prevent NoSQL injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    console.warn(`Sanitized NoSQL injection attempt: ${key}`);
  }
}));

// Parameterized queries for SQL
const { Pool } = require('pg');
const pool = new Pool();

// UNSAFE - vulnerable to SQL injection
