// Secure Secrets Management Configuration

const dotenv = require('dotenv');
const path = require('path');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.requiredSecrets = new Set();
    this.validated = false;
  }

  // Initialize environment variables
  initialize() {
    // Determine environment
    const env = process.env.NODE_ENV || 'development';

    // Load appropriate .env file
    const envPath = path.join(__dirname, '..', `.env.${env}`);
    const result = dotenv.config({ path: envPath });

    if (result.error && env === 'production') {
      console.warn(`Warning: Could not load ${envPath} in production`);
    } else if (result.error && env !== 'test') {
      console.warn(`Warning: Could not load ${envPath}`);
    }

    // Load common .env file if exists
    dotenv.config({ path: path.join(__dirname, '..', '.env') });

    // Store secrets from process.env
    this.loadFromProcessEnv();

    return this;
  }

  // Add required secret validation
  requireSecret(key, description) {
    this.requiredSecrets.add(key);
    return this;
  }

  // Validate all required secrets are present
  validate() {
    const missingSecrets = [];

    for (const secretKey of this.requiredSecrets) {
      if (!this.secrets.has(secretKey) || !this.secrets.get(secretKey)) {
        missingSecrets.push(secretKey);
      }
    }

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    this.validated = true;
    return this;
  }

  // Get secret with validation
  get(key, defaultValue = null) {
    if (!this.validated && this.requiredSecrets.has(key)) {
      throw new Error('Secrets not validated. Call validate() first.');
    }

    const value = this.secrets.get(key) || defaultValue;

    // Log access for audit trail (in development only)
    if (process.env.NODE_ENV === 'development') {
      console.debug(`Secret accessed: ${key} (${value ? 'present' : 'missing'})`);
    }

    return value;
  }

  // Check if secret exists
  has(key) {
    return this.secrets.has(key) && !!this.secrets.get(key);
  }

  // Load secrets from process.env
  loadFromProcessEnv() {
    // Define which environment variables are considered secrets
    const secretKeys = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DATABASE_URL',
      'DB_PASSWORD',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'REDIS_PASSWORD'
    ];

    // Also include any variable with "SECRET", "KEY", "PASSWORD", "TOKEN" in name
    for (const [key, value] of Object.entries(process.env)) {
      if (value && 
          (secretKeys.includes(key) || 
           /(SECRET|KEY|PASSWORD|TOKEN|PASSWD|CREDENTIAL)/i.test(key))) {
        // Mask the value for logging
        const maskedValue = this.maskSecret(value);

        // Store the actual value
        this.secrets.set(key, value);

        // Log loading (with masking)
        if (process.env.NODE_ENV !== 'production') {
          console.debug(`Loaded secret: ${key}=${maskedValue}`);
        }
      }
    }
  }

  // Mask secret for logging
  maskSecret(value) {
    if (!value || value.length < 8) {
      return '***';
    }
    return `${value.substring(0, 2)}***${value.substring(value.length - 2)}`;
  }

  // Get all secrets (masked) for debugging
  getAllMasked() {
    const masked = {};
    for (const [key, value] of this.secrets.entries()) {
      masked[key] = this.maskSecret(value);
    }
    return masked;
  }

  // Rotate a secret (simulated - in production would call external service)
  rotateSecret(key, newValue) {
    if (!this.secrets.has(key)) {
      throw new Error(`Secret ${key} does not exist`);
    }

    const oldValue = this.secrets.get(key);
    this.secrets.set(key, newValue);

    // In production, would also update external secrets manager
    console.log(`Rotated secret: ${key}`);

    return { rotated: true, key };
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Initialize with required secrets
module.exports = secretsManager
  .initialize()
  .requireSecret('JWT_SECRET', 'JWT signing secret')
  .requireSecret('SESSION_SECRET', 'Session encryption secret')
  .validate();

// Express.js Application with Secure Secret Management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const secrets = require('./config/secrets');

const app = express();

// ====================
// SECURITY CONFIGURATION
// ====================

// Get configuration from secrets manager
const PORT = secrets.get('PORT', 3000);
const NODE_ENV = secrets.get('NODE_ENV', 'development');

// 1. Security headers
app.use(helmet());

// 2. CORS configuration
const corsOptions = {
  origin: secrets.get('ALLOWED_ORIGINS', 'http://localhost:3000')?.split(','),
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(secrets.get('RATE_LIMIT_WINDOW_MS', 15 * 60 * 1000)),
  max: parseInt(secrets.get('RATE_LIMIT_MAX_REQUESTS', 100)),
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: secrets.get('BODY_SIZE_LIMIT', '10kb') }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: secrets.get('BODY_SIZE_LIMIT', '10kb') 
}));

// ====================
// SECURITY MIDDLEWARE
// ====================

// Log secret access (development only)
if (NODE_ENV === 'development') {
  app.use((req, res, next) => {
    const originalSend = res.send;
    res.send = function(data) {
      // Check if any secret was exposed in response
      const secretsExposed = [];
      const secretValues = Array.from(secrets.secrets.values());

      if (typeof data === 'string') {
        for (const secret of secretValues) {
          if (data.includes(secret)) {
            secretsExposed.push('***SECRET EXPOSED***');
            console.error(`CRITICAL: Secret exposed in response to ${req.path}`);
          }
        }
      }

      return originalSend.call(this, data);
    };
    next();
  });
}

// Prevent secret leakage in error responses
app.use((err, req, res, next) => {
  // Ensure no secrets are exposed in error messages
  const secretValues = Array.from(secrets.secrets.values());
  let safeErrorMessage = err.message;

  for (const secret of secretValues) {
    if (secret && safeErrorMessage.includes(secret)) {
      safeErrorMessage = safeErrorMessage.replace(
        secret, 
        '***SECRET***'
      );
    }
  }

  const safeError = {
    ...err,
    message: safeErrorMessage,
    // Remove stack trace in production
    stack: NODE_ENV === 'development' ? err.stack : undefined
  };

  next(safeError);
});

// ====================
// ROUTES
// ====================

// Health endpoint - reveals minimal information
app.get('/health', (req, res) => {
  // Only reveal non-sensitive information
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: secrets.get('APP_VERSION', '1.0.0'),
    environment: NODE_ENV
  });
});

// Protected users endpoint
app.get('/users', (req, res) => {
  // Validate API key if provided
  const apiKey = req.headers['x-api-key'];
  const validApiKey = secrets.get('API_KEY');

  if (validApiKey && apiKey !== validApiKey) {
    return res.status(401).json({ 
      error: 'Invalid API key',
      // Don't reveal whether API key is required or not
      message: 'Authentication required'
    });
  }

  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// Secret validation endpoint (protected)
app.get('/secrets/validate', (req, res) => {
  // Only allow in development
  if (NODE_ENV !== 'development') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({
    status: 'validated',
    requiredSecrets: Array.from(secrets.requiredSecrets),
    missingSecrets: Array.from(secrets.requiredSecrets)
      .filter(key => !secrets.has(key)),
    maskedSecrets: secrets.getAllMasked()
  });
});

// ====================
// SECURITY CHECKS
// ====================

// Check for default/dangerous secrets on startup
function performSecurityChecks() {
  console.log(`Starting security checks for ${NODE_ENV} environment...`);

  // Check for default/dangerous secrets
  const dangerousDefaults = {
    'JWT_SECRET': ['secret', 'changeme', 'jwtsecret'],
    'SESSION_SECRET': ['secret', 'keyboard cat', 'sessionsecret']
  };

  let issuesFound = false;

  for (const [secretKey, dangerousValues] of Object.entries(dangerousDefaults)) {
    const currentValue = secrets.get(secretKey);

    if (currentValue && dangerousValues.includes(currentValue.toLowerCase())) {
      console.error(`SECURITY WARNING: ${secretKey} is using a default/dangerous value!`);
      issuesFound = true;
    }
  }

  // Check if running with development secrets in production
  if (NODE_ENV === 'production') {
    const devSecrets = secrets.get('DEV_SECRETS', 'false');
    if (devSecrets === 'true') {
      console.error('CRITICAL: Running production with development secrets!');
      issuesFound = true;
    }
  }

  if (!issuesFound) {
    console.log('Security checks passed.');
  }

  return !issuesFound;
}

// ====================
// SERVER STARTUP
// ====================

// Perform security checks before starting
if (performSecurityChecks()) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${NODE_ENV}`);
    console.log(`Secrets loaded: ${secrets.secrets.size}`);

    // Never log actual secrets
    if (NODE_ENV === 'development') {
      console.log('Masked secrets:', secrets.getAllMasked());
    }
  });
} else {
  console.error('Server failed to start due to security issues.');
  process.exit(1);
}

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  // Clear secrets from memory as much as possible
  secrets.secrets.clear();
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  secrets.secrets.clear();
  process.exit(0);
});

module.exports = app;

