// Security Headers Implementation Example
const express = require('express');
const helmet = require('helmet');

const app = express();

// Use helmet with specific configurations
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Input Validation Implementation Example
const { validationResult, checkSchema } = require('express-validator');

// Example validation schema for user input
const userValidationSchema = {
  id: {
    in: ['params', 'query'],
    isInt: true,
    toInt: true,
    optional: false
  },
  name: {
    in: ['body'],
    isString: true,
    isLength: {
      options: { min: 2, max: 50 }
    },
    trim: true,
    escape: true,
    optional: true
  },
  email: {
    in: ['body'],
    isEmail: true,
    normalizeEmail: true,
    optional: true
  },
  limit: {
    in: ['query'],
    isInt: {
      options: { min: 1, max: 100 }
    },
    optional: true,
    toInt: true
  }
};

// Middleware to validate input
const validateInput = (schema) => {
  return [
    checkSchema(schema),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          errors: errors.array(),
          message: 'Validation failed'
        });
      }
      next();
    }
  ];
};

// Example route with validation
app.get('/users/:id', validateInput(userValidationSchema), (req, res) => {
  const { id } = req.params;
  // Safe to use the validated ID
  res.json({ id, name: 'User Name' });
});

// SQL Injection Prevention Example
const sanitizeForSQL = (input) => {
  // Use parameterized queries with database library
  // This is just a demonstration - actual implementation depends on DB driver
  if (typeof input !== 'string') return input;
  return input.replace(/['";\\]/g, ''); // Basic sanitization
};

// XSS Prevention
const sanitizeHTML = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
};

// Authentication & Authorization Example
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');

// Rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests per windowMs
  message: 'Too many login attempts, please try again later',
  standardHeaders: true,
  legacyHeaders: false
});

// JWT Authentication Middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ message: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ message: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Role-based Authorization Middleware
const authorizeRoles = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ message: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ 
        message: 'Insufficient permissions' 
      });
    }
    next();
  };
};

// Example login endpoint with rate limiting and security
app.post('/api/auth/login', authLimiter, async (req, res) => {
  try {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
      return res.status(400).json({ message: 'Username and password required' });
    }

    // In production: Fetch user from database
    // This is a simplified example
    const user = await getUserFromDatabase(username);

    if (!user) {
      // Use same response for both invalid user and password to prevent user enumeration
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    // Compare passwords (always use async bcrypt)
    const validPassword = await bcrypt.compare(password, user.passwordHash);

    if (!validPassword) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    // Generate JWT token
    const token = jwt.sign(
      { 
        userId: user.id, 
        username: user.username,
        role: user.role 
      },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );

    // Set secure cookie if using cookies
    res.cookie('token', token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 60 * 60 * 1000 // 1 hour
    });

    res.json({ 
      token,
      user: {
        id: user.id,
        username: user.username,
        role: user.role
      }
    });

  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Protected route example
app.get('/api/admin/users', authenticateToken, authorizeRoles('admin'), (req, res) => {
  // Only accessible by admin users
  res.json({ message: 'Admin users data' });
});

// Environment Variable Security Example
require('dotenv').config();
const helmet = require('helmet');

// Validate required environment variables on startup
const requiredEnvVars = [
  'NODE_ENV',
  'JWT_SECRET',
  'PORT'
];

const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingVars.length > 0) {
  console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

// Security middleware that hides sensitive headers
app.use((req, res, next) => {
  // Remove sensitive headers from responses
  res.removeHeader('X-Powered-By');
  res.removeHeader('Server');
  next();
});

// Never expose sensitive env vars in responses
app.use((req, res, next) => {
  // Ensure no API keys or secrets are accidentally exposed
  const safeEnvVars = {
    nodeEnv: process.env.NODE_ENV,
    // Only expose non-sensitive environment variables
  };

  // Override res.locals to prevent accidental exposure
  res.locals.env = safeEnvVars;
  next();
});

// Security audit endpoint
app.get('/api/security/audit', authenticateToken, authorizeRoles('admin'), (req, res) => {
  // Log security events
  console.log(`Security audit accessed by ${req.user.username} at ${new Date().toISOString()}`);

  res.json({
    status: 'secure',
    timestamp: new Date().toISOString(),
    security_headers: {
      content_security_policy: true,
      hsts: true,
      x_frame_options: true,
      x_content_type_options: true,
      x_xss_protection: true
    },
    rate_limiting: true,
    authentication: true,
    input_validation: true
  });
});

// Environment variable validation function
const validateEnvVar = (varName, pattern = null) => {
  const value = process.env[varName];
  if (!value) {
    throw new Error(`Environment variable ${varName} is not set`);
  }

  if (pattern && !pattern.test(value)) {
    throw new Error(`Environment variable ${varName} does not match required pattern`);
  }

  return value;
};

// Complete Secure Express Application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const { validationResult, checkSchema } = require('express-validator');

const app = express();

// ======================
// SECURITY CONFIGURATION
// ======================

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
}));

// 3. Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts',
  standardHeaders: true
});

// 4. Compression (after security middleware)
app.use(compression());

// 5. Request Parsing with Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 6. Security Logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks
}));

// 7. Remove sensitive headers
app.disable('x-powered-by');

// ======================
// INPUT VALIDATION
// ======================

const userValidationSchema = {
  id: {
    in: ['params', 'query'],
    isInt: { options: { min: 1 } },
    toInt: true,
    errorMessage: 'ID must be a positive integer'
  },
  name: {
    in: ['body'],
    isString: true,
    isLength: { options: { min: 2, max: 100 } },
    trim: true,
    escape: true,
    errorMessage: 'Name must be between 2 and 100 characters'
  },
  email: {
    in: ['body'],
    isEmail: true,
    normalizeEmail: true,
    errorMessage: 'Invalid email address'
  }
};

const validateInput = (schema) => {
  return [
    checkSchema(schema),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false,
          errors: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        });
      }
      next();
    }
  ];
};

// ======================
// SECURE ENDPOINTS
// ======================

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// Health check (public)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Example secure user endpoint
app.get('/api/users/:id', validateInput({ id: userValidationSchema.id }), (req, res) => {
  try {
    const { id } = req.params;

    // In production: Fetch from database with parameterized queries
    const user = { id: parseInt(id), name: 'John Doe', email: 'john@example.com' };

    res.json({
      success: true,
      data: user
    });

  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// ======================
// ERROR HANDLING
// ======================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found'
  });
});

// Error handler
app.use((error, req, res, next) => {
  console.error('Application error:', error);

  // Don't expose error details in production
  const response = {
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = error.stack;
  }

  res.status(error.status || 500).json(response);
});

// ======================
// SECURITY UTILITIES
// ======================

// Security headers check
const checkSecurityHeaders = () => {
  const requiredHeaders = [
    'X-Content-Type-Options',
    'X-Frame-Options',
    'X-XSS-Protection',
    'Strict-Transport-Security'
  ];

  // This would be called during app initialization
  console.log('Security headers configured');
};

// Initialize security checks
checkSecurityHeaders();

// ======================
// SERVER STARTUP
// ======================

const PORT = process.env.PORT || 3000;

// Security validation before starting
const validateSecurityConfig = () => {
  const issues = [];

  if (process.env.NODE_ENV === 'production' && !process.env.JWT_SECRET) {
    issues.push('JWT_SECRET not set in production');
  }

  if (process.env.NODE_ENV === 'production' && process.env.PORT === '3000') {
    console.warn('Warning: Using default port 3000 in production');
  }

  return issues;
};

const securityIssues = validateSecurityConfig();
if (securityIssues.length > 0) {
  console.error('Security configuration issues:', securityIssues);
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

module.exports = {
  env: {
    node: true,
    es2021: true,
    jest: true
  },
  extends: [
    'eslint:recommended',
    'airbnb-base',
    'plugin:security/recommended'
  ],
  plugins: [
    'security',
    'import'
  ],
  parserOptions: {
    ecmaVersion: 'latest',
    sourceType: 'module'
  },
  rules: {
    // Security-specific rules
    'security/detect-buffer-noassert': 'error',
    'security/detect-child-process': 'error',
    'security/detect-disable-mustache-escape': 'error',
    'security/detect-eval-with-expression': 'error',
    'security/detect-new-buffer': 'error',
    'security/detect-no-csrf-before-method-override': 'error',
    'security/detect-non-literal-fs-filename': 'warn',
    'security/detect-non-literal-regexp': 'error',
    'security/detect-non-literal-require': 'warn',
    'security/detect-object-injection': 'warn',
    'security/detect-possible-timing-attacks': 'error',
    'security/detect-pseudoRandomBytes': 'error',

    // General security best practices
    'no-eval': 'error',
    'no-implied-eval': 'error',
    'no-script-url': 'error',
    'no-console': process.env.NODE_ENV === 'production' ? 'error' : 'warn',

    // Code quality
    'no-unused-vars': ['error', { argsIgnorePattern: '^_' }],
    'consistent-return': 'error',
    'no-shadow': 'error',
    'no-param-reassign': ['error', { props: false }],

    // Import/export rules
    'import/order': ['error', {
      groups: ['builtin', 'external', 'internal', 'parent', 'sibling', 'index'],
      'newlines-between': 'always',
      alphabetize: { order: 'asc', caseInsensitive: true }
    }],

    // Error handling
    'no-throw-literal': 'error',
    'prefer-promise-reject-errors': 'error'
  },
  settings: {
    'import/resolver': {
      node: {
        extensions: ['.js', '.jsx', '.ts', '.tsx']
      }
    }
  },
  ignorePatterns: [
    'node_modules/',
    'dist/',
    'build/',
    'coverage/',
    '*.min.js',
    'security_headers_example.js',
    'input_validation_example.js',
    'auth_example.js',
    'env_security_example.js'
  ]
};

