// SECRETS MANAGEMENT BEST PRACTICES
// OWASP A02:2021 - Cryptographic Failures

// ============================================
// OPTION 1: Environment Variables (Basic)
// ============================================
// Only for non-sensitive or development use
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config({ path: '.env.development' });
}

// ============================================
// OPTION 2: AWS Secrets Manager (Recommended)
// ============================================
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({
          SecretId: secretName,
          VersionStage: 'AWSCURRENT'
        })
      );

      const secretValue = response.SecretString;
      const parsedSecret = JSON.parse(secretValue);

      // Cache the result
      this.cache.set(secretName, {
        value: parsedSecret,
        timestamp: Date.now()
      });

      return parsedSecret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Clear cache (useful for testing or rotation)
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

// ============================================
// OPTION 3: HashiCorp Vault
// ============================================
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });
  }

  async getSecret(path) {
    try {
      const response = await this.client.read(path);
      return response.data;
    } catch (error) {
      console.error(`Vault error reading ${path}:`, error);
      throw error;
    }
  }
}

// ============================================
// UNIFIED SECRETS LOADER
// ============================================
class SecretsLoader {
  constructor(strategy = 'env') {
    this.strategy = process.env.SECRETS_STRATEGY || strategy;
    this.secrets = {};

    if (this.strategy === 'aws' && !process.env.AWS_REGION) {
      throw new Error('AWS_REGION required for AWS Secrets Manager');
    }

    this.init();
  }

  async init() {
    // Load configuration-based secrets
    await this.loadConfiguration();
  }

  async loadConfiguration() {
    switch (this.strategy) {
      case 'aws':
        this.manager = new AWSecretsManager();
        break;
      case 'vault':
        this.manager = new VaultSecretsManager();
        break;
      case 'env':
      default:
        // Environment variables already loaded
        break;
    }
  }

  async get(key, fallback = null) {
    // Priority: Secrets Manager > Environment > Fallback
    let value = null;

    try {
      switch (this.strategy) {
        case 'aws':
        case 'vault':
          // Get from secrets manager
          const secret = await this.manager.getSecret(`app/${process.env.NODE_ENV}/${key}`);
          value = secret[key] || secret.value;
          break;
        case 'env':
          value = process.env[key];
          break;
      }
    } catch (error) {
      console.warn(`Could not retrieve secret ${key} from ${this.strategy}:`, error.message);
    }

    // Fallback to environment variable if available
    if (!value && process.env[key]) {
      value = process.env[key];
    }

    // Final fallback
    if (!value && fallback !== null) {
      value = fallback;
    }

    if (!value) {
      throw new Error(`Secret ${key} not found and no fallback provided`);
    }

    return value;
  }

  // For sensitive values that should be encrypted at rest
  async getEncrypted(key) {
    const encryptedValue = await this.get(key);
    // In practice, you would decrypt here with KMS or similar
    return encryptedValue;
  }
}

// ============================================
// SECRETS VALIDATION & ROTATION
// ============================================

// Secret validation on startup
const validateSecrets = async () => {
  const requiredSecrets = [
    'JWT_SECRET',
    'DATABASE_URL',
    // Add other required secrets
  ];

  const loader = new SecretsLoader();
  const missing = [];

  for (const secret of requiredSecrets) {
    try {
      await loader.get(secret);
    } catch (error) {
      missing.push(secret);
    }
  }

  if (missing.length > 0) {
    console.error(`Missing required secrets: ${missing.join(', ')}`);

    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    } else {
      console.warn('Running with missing secrets in non-production environment');
    }
  }
};

// Secret rotation handler
const setupSecretRotation = () => {
  // Listen for secret rotation events
  if (process.env.SECRETS_STRATEGY === 'aws') {
    // AWS Secrets Manager rotation
    process.on('SIGHUP', async () => {
      console.log('Secret rotation signal received, clearing cache...');
      const loader = new SecretsLoader('aws');
      loader.manager.clearCache();
      await validateSecrets();
    });
  }
};

// ============================================
// USAGE EXAMPLE
// ============================================

// Initialize secrets
const secrets = new SecretsLoader();

// In your application
app.get('/secure-endpoint', async (req, res) => {
  try {
    // Get JWT secret from secure storage
    const jwtSecret = await secrets.get('JWT_SECRET');

    // Get database URL
    const dbUrl = await secrets.getEncrypted('DATABASE_URL');

    // Use secrets securely
    // ... your code here ...

    res.json({ success: true });
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    res.status(500).json({ error: 'Configuration error' });
  }
});

// Startup validation
validateSecrets().then(() => {
  console.log('Secrets validated successfully');
  setupSecretRotation();
}).catch(error => {
  console.error('Failed to validate secrets:', error);
  process.exit(1);
});

module.exports = {
  SecretsLoader,
  validateSecrets,
  setupSecretRotation
};

